/**
 * ClubGG cards off the screen: the board (and, later, hero's hole cards) by TEMPLATE MATCHING — Windows' OCR reads
 * no single large glyph (tried: a rank corner cut out, cleaned and padded gave nothing).
 *
 * Geometry is in REFERENCE pixels, a 1698x1260 table client (the 200% DPI window the templates were cut from); a
 * table of another size scales by width. Board slot k's card has its left edge at 528 + 130k and its top at 530 —
 * or 490 when the showdown RAISES the winning five (the other board cards are dimmed grey then: no white, "absent").
 *
 * A glyph = the ink (dark, or card red) in a box, cut to its bounding box and shrunk to 20x28 by PIL's BOX filter,
 * then >= 0.5. The templates are majority votes over every board card of recording 20260928_194914 (2179 cards, one
 * cluster per rank shape and colour, labelled by eye; poker-data/clubgg/card_templates.py): rank from the corner
 * (L+4..L+58, T+4..T+58), suit from the pip under it (L+4..L+58, T+60..T+104).
 */
import type { Bgra } from "./cggOcr";

export const REF_W = 1698;
export const REF_H = 1260;

/** [label, 560 cells of 0/1, 20 wide, row by row]. Several per rank: red and black print differently. */
export const RANK_TEMPLATES: [string, string][] = [
  ["6", ""],
  ["7", ""],
  ["8", ""],
  ["9", ""],
  ["6", ""],
  ["K", ""],
  ["4", ""],
  ["Q", ""],
  ["T", ""],
  ["7", ""],
  ["2", ""],
  ["2", ""],
  ["A", ""],
  ["8", ""],
  ["T", ""],
  ["J", ""],
  ["J", ""],
  ["5", ""],
  ["5", ""],
  ["K", ""],
  ["4", ""],
  ["A", ""],
  ["3", ""],
];
export const SUIT_TEMPLATES: [string, string][] = [
  ["s", ""],
  ["h", ""],
  ["d", ""],
  ["c", ""],
];

/** Bet-pill digits [label, 216 cells of 0/1, 12 wide] (poker-data/clubgg/digit_templates.py: 1,500 glyphs labelled by OCR). */
export const DIGIT_TEMPLATES: [string, string][] = [
  ["0", "000011110000001111111100011111111110011100001110111000000111111000000111111000000111111000000111111000000111111000000111111000000111111000000111111000000111011000000110011100001110011111111110001111111100000001100000"],
  ["1", "000001111111111111111111111111111111111111111111110000011111000000011111000000011111000000011111000000011111000000011111000000011111000000011111000000011111000000011111000000011111000000011111000000011111000000011111"],
  ["2", "000111110000001111111100011111111110111000001110111000001110111000001110000000001110000000001110000000011110000000011100000001111000000011110000000111100000001111000000001110000000011110000000111111111111111111111111"],
  ["3", "000111110000011111111100111111111110111000001110000000001110000000001110000000001110000111111100000111111100000111111100000000011110000000001110000000000111111000001111111000001110111111111110011111111100000011100000"],
  ["4", "000000011100000000011100000001111100000011111100000011111100000011111100000111111100000110011100001110011100011100011100011000011100111011111110111111111111111111111111111111111111000000011100000000011100000000011100"],
  ["5", "001111111110011111111110011111111111011100000000011100000000011100000000011111111000111111111110011100011110011100011111000000001111000000000111000000000111111000001111111100001111011111111110011111111110000011110000"],
  ["6", "000000011100000011111100000111111100001110000000011100000000011100000000011100000000011111111100111111111110111100001111111000000111111000000111111000000111011100000111011100000111011100001111001111111110000111111100"],
  ["7", "111111111111111111111111111111111111000000001110000000001110000000001110000000001110000000011100000000011100000001111000000001111000000001110000000011110000000011100000000011100000000111100000000111100000001110000000"],
  ["8", "000011110000001111111100011111111110011100001110011100000111011100000111011100001110001111111110001111111100001111111100011110011110011100000111111000000111111000000111111100001111011111111110001111111110000011110000"],
  ["9", "000011110000001111111100011110011110011100001110111100000111111100000111111000000111111000000111011100000111011100001111011111111111000111110111000000001110000000001110000000001110000000011100000111111000000111110000"],
];

const bits = (s: string) => Uint8Array.from(s, (c) => (c === "1" ? 1 : 0));
const RANKS = RANK_TEMPLATES.map(([l, s]) => [l, bits(s)] as const);
const SUITS = SUIT_TEMPLATES.map(([l, s]) => [l, bits(s)] as const);
const DIGITS = DIGIT_TEMPLATES.map(([l, s]) => [l, bits(s)] as const);

// ---- pixels ----------------------------------------------------------------------------------------------

export type RGB = [number, number, number];

/** [r, g, b] at (x, y) of a BGRA frame (outside = black). */
export function rgb(f: Bgra, x: number, y: number): RGB {
  x = Math.trunc(x); y = Math.trunc(y);
  if (x < 0 || y < 0 || x >= f.width || y >= f.height) return [0, 0, 0];
  const o = (y * f.width + x) * 4;
  return [f.bgra[o + 2]!, f.bgra[o + 1]!, f.bgra[o]!];
}

export const isWhite = (c: RGB) => Math.min(c[0], c[1], c[2]) > 200;
export const isRed = (c: RGB) => c[0] > 140 && c[1] < 100 && c[2] < 100;
export const isInk = (c: RGB) => Math.max(c[0], c[1], c[2]) < 110 || isRed(c);

/** Share of pixels in a box (frame pixels) that pass `test`, sampled every `step` pixels. */
export function share(f: Bgra, x0: number, y0: number, x1: number, y1: number, test: (c: RGB) => boolean, step = 1): number {
  let n = 0, hit = 0;
  for (let y = Math.trunc(y0); y < y1; y += step) {
    for (let x = Math.trunc(x0); x < x1; x += step) {
      n++;
      if (test(rgb(f, x, y))) hit++;
    }
  }
  return n ? hit / n : 0;
}

// ---- glyphs ----------------------------------------------------------------------------------------------

/** PIL's resample coefficients for the BOX filter (precompute_coeffs), one output axis. */
function boxCoeffs(inSize: number, outSize: number): { min: number; w: number[] }[] {
  const scale = inSize / outSize;
  const filterscale = Math.max(1.0, scale);
  const support = 0.5 * filterscale;
  const out: { min: number; w: number[] }[] = [];
  for (let xx = 0; xx < outSize; xx++) {
    const center = (xx + 0.5) * scale;
    let xmin = Math.trunc(center - support + 0.5);
    if (xmin < 0) xmin = 0;
    let xmax = Math.trunc(center + support + 0.5);
    if (xmax > inSize) xmax = inSize;
    const w: number[] = [];
    let ww = 0;
    for (let x = 0; x < xmax - xmin; x++) {
      const t = (x + xmin - center + 0.5) / filterscale;
      const v = t > -0.5 && t <= 0.5 ? 1.0 : 0.0;
      w.push(v);
      ww += v;
    }
    out.push({ min: xmin, w: w.map((v) => (ww ? v / ww : 0)) });
  }
  return out;
}

/** A 0/1 mask cut to its bounding box and shrunk to GWxGH (BOX, then >= 0.5), or null when it holds < `min` pixels. */
export function normGlyph(mask: Uint8Array, w: number, h: number, GW = 20, GH = 28, min = 20): Uint8Array | null {
  let x0 = w, y0 = h, x1 = -1, y1 = -1, n = 0;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (!mask[y * w + x]) continue;
      n++;
      if (x < x0) x0 = x;
      if (x > x1) x1 = x;
      if (y < y0) y0 = y;
      if (y > y1) y1 = y;
    }
  }
  if (n < min) return null;
  const bw = x1 - x0 + 1, bh = y1 - y0 + 1;
  const cx = boxCoeffs(bw, GW), cy = boxCoeffs(bh, GH);
  const tmp = new Float64Array(GW * bh);          // horizontal pass
  for (let y = 0; y < bh; y++) {
    for (let xx = 0; xx < GW; xx++) {
      const c = cx[xx]!;
      let acc = 0;
      for (let k = 0; k < c.w.length; k++) acc += c.w[k]! * mask[(y0 + y) * w + x0 + c.min + k]!;
      tmp[y * GW + xx] = acc;
    }
  }
  const out = new Uint8Array(GW * GH);             // vertical pass
  for (let yy = 0; yy < GH; yy++) {
    const c = cy[yy]!;
    for (let xx = 0; xx < GW; xx++) {
      let acc = 0;
      for (let k = 0; k < c.w.length; k++) acc += c.w[k]! * tmp[(c.min + k) * GW + xx]!;
      out[yy * GW + xx] = acc >= 0.5 ? 1 : 0;
    }
  }
  return out;
}

/** The ink mask of a box of the frame (frame pixels), and how many of its pixels are card red. */
export function inkBox(f: Bgra, x0: number, y0: number, x1: number, y1: number): { mask: Uint8Array; w: number; h: number; red: number } {
  x0 = Math.round(x0); y0 = Math.round(y0); x1 = Math.round(x1); y1 = Math.round(y1);
  const w = Math.max(0, x1 - x0), h = Math.max(0, y1 - y0);
  const mask = new Uint8Array(w * h);
  let red = 0;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const c = rgb(f, x0 + x, y0 + y);
      if (isRed(c)) red++;
      if (isInk(c)) mask[y * w + x] = 1;
    }
  }
  return { mask, w, h, red };
}

export type Match = { label: string; score: number; second: number };

/** The best template for a normalised glyph: share of the 560 cells that agree, and the runner-up's (other label). */
export function bestOf(g: Uint8Array, set: readonly (readonly [string, Uint8Array])[]): Match {
  const byLabel = new Map<string, number>();
  for (const [label, t] of set) {
    let same = 0;
    for (let i = 0; i < t.length; i++) if (t[i] === g[i]) same++;
    const s = same / t.length;
    if (s > (byLabel.get(label) ?? -1)) byLabel.set(label, s);
  }
  const ranked = [...byLabel].sort((a, b) => b[1] - a[1]);
  return { label: ranked[0]![0], score: ranked[0]![1], second: ranked[1]?.[1] ?? 0 };
}

/** Below this share of agreeing cells a glyph is "not a card we know" (a template agrees ~0.97 with its own). */
export const MIN_SCORE = 0.8;

/** A card's rank + suit from its top-left corner (frame pixels; s = frame px per reference px). */
export function readCardAt(f: Bgra, L: number, T: number, s: number): { card: string | null; rank: Match | null; suit: Match | null; red: boolean } {
  const rk = inkBox(f, L + 4 * s, T + 4 * s, L + 58 * s, T + 58 * s);
  const sp = inkBox(f, L + 4 * s, T + 60 * s, L + 58 * s, T + 104 * s);
  const rn = normGlyph(rk.mask, rk.w, rk.h), sn = normGlyph(sp.mask, sp.w, sp.h);
  const rank = rn ? bestOf(rn, RANKS) : null;
  const red = sp.red > 30 * s * s;
  // colour settles the suit pair; the shape picks within it
  const suit = sn ? bestOf(sn, SUITS.filter(([l]) => (red ? l === "h" || l === "d" : l === "s" || l === "c"))) : null;
  const ok = !!rank && !!suit && rank.score >= MIN_SCORE && suit.score >= MIN_SCORE;
  return { card: ok ? rank!.label + suit!.label : null, rank, suit, red };
}

export type BoardSlot = { present: boolean; raised: boolean; card: string | null; score: number };

/** The five board slots. `present` = a white card face is there (dimmed showdown cards are not). */
export function readBoard(f: Bgra): BoardSlot[] {
  const s = f.width / REF_W;
  const out: BoardSlot[] = [];
  for (let k = 0; k < 5; k++) {
    const L = (528 + 130 * k) * s;
    let T: number | null = null;
    // the top edge: the first 15-pixel white run down the column band right of the rank (x L+86..L+95)
    let run = 0;
    for (let y = 480; y < 560; y++) {
      const white = share(f, L + 86 * s, y * s, L + 95 * s, y * s + 1, isWhite) > 0.8;
      run = white ? run + 1 : 0;
      if (run >= 15) {
        T = y - 14;
        break;
      }
    }
    if (T === null || share(f, L + 70 * s, (T + 5) * s, L + 112 * s, (T + 40) * s, isWhite, 2) < 0.8) {
      out.push({ present: false, raised: false, card: null, score: 0 });
      continue;
    }
    const r = readCardAt(f, L, T * s, s);
    out.push({ present: true, raised: T < 510, card: r.card, score: Math.min(r.rank?.score ?? 0, r.suit?.score ?? 0) });
  }
  return out;
}

// ---- bet pills --------------------------------------------------------------------------------------------
// A bet (and the swept pot under the board) is a number in a DARK PILL on the felt: greenish black (~15,45,17) on felt
// (~34,100,38) — the rail is black with no green in it. Windows' OCR misses these short numbers on many frames
// (20260928_194914 #1653: "2", "1", "6", "6" all on screen, OCR gave "ee"), so they are read by digit templates.

export type Pill = { x: number; y: number; w: number; h: number; cx: number; cy: number; text: string | null; value: number | null };

const isPillPx = (c: RGB) => Math.max(c[0], c[1], c[2]) < 62 && c[1] > c[0] + 12 && c[1] > c[2] + 12;

/** 0/1 mask components (4- or 8-connected): bounding box + pixel count + member mask. */
export function components(mask: Uint8Array, w: number, h: number, eight: boolean): { x: number; y: number; w: number; h: number; n: number; px: number[] }[] {
  const lab = new Int32Array(w * h);
  const out: { x: number; y: number; w: number; h: number; n: number; px: number[] }[] = [];
  const stack: number[] = [];
  for (let i = 0; i < w * h; i++) {
    if (!mask[i] || lab[i]) continue;
    const id = out.length + 1;
    let x0 = w, y0 = h, x1 = -1, y1 = -1;
    const px: number[] = [];
    lab[i] = id;
    stack.push(i);
    while (stack.length) {
      const j = stack.pop()!;
      px.push(j);
      const x = j % w, y = (j - x) / w;
      if (x < x0) x0 = x;
      if (x > x1) x1 = x;
      if (y < y0) y0 = y;
      if (y > y1) y1 = y;
      for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          if (!dx && !dy) continue;
          if (!eight && dx && dy) continue;
          const xx = x + dx, yy = y + dy;
          if (xx < 0 || yy < 0 || xx >= w || yy >= h) continue;
          const k = yy * w + xx;
          if (mask[k] && !lab[k]) {
            lab[k] = id;
            stack.push(k);
          }
        }
      }
    }
    out.push({ x: x0, y: y0, w: x1 - x0 + 1, h: y1 - y0 + 1, n: px.length, px });
  }
  return out;
}

/** The number in one pill (frame pixels in, text out): its light glyphs left to right, a narrow one = "1", a small low
 *  one = "." (or "," when it hangs below the digits), the rest by template. Null when a glyph matches nothing. */
export function readPillText(f: Bgra, x: number, y: number, w: number, h: number): string | null {
  const mask = new Uint8Array(w * h);
  for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) if (Math.min(...rgb(f, x + i, y + j)) > 150) mask[j * w + i] = 1;
  const gs = components(mask, w, h, true).filter((g) => g.n >= 3).sort((a, b) => a.x - b.x);
  if (!gs.length) return null;
  const hmax = Math.max(...gs.map((g) => g.h));
  const base = Math.max(...gs.filter((g) => g.h >= 0.6 * hmax).map((g) => g.y + g.h));
  let text = "";
  for (const g of gs) {
    if (g.h < 0.6 * hmax) {
      text += g.y + g.h > base + 1 ? "," : ".";
      continue;
    }
    if (g.w < 0.45 * g.h) {
      text += "1";
      continue;
    }
    const m = new Uint8Array(g.w * g.h);
    for (const k of g.px) {
      const xx = k % w, yy = (k - xx) / w;
      m[(yy - g.y) * g.w + (xx - g.x)] = 1;
    }
    const n = normGlyph(m, g.w, g.h, 12, 18, 3);
    if (!n) return null;
    // "1" is the narrow one (w/h ~0.4; the rest ~0.6-0.7): between 0.45 and 0.55 its template competes, above it cannot
    const best = bestOf(n, DIGITS.filter(([l]) => l !== "1" || g.w < 0.55 * g.h));
    if (best.score < 0.78) return null;
    text += best.label;
  }
  return text;
}

/** Every pill on the felt (reference px), with its number when it reads as one. */
export function readPills(f: Bgra): Pill[] {
  const s = f.width / REF_W;
  const step = Math.max(1, Math.round(2 * s));
  const X0 = Math.round(120 * s), X1 = Math.round(1580 * s), Y0 = Math.round(330 * s), Y1 = Math.round(980 * s);
  const gw = Math.ceil((X1 - X0) / step), gh = Math.ceil((Y1 - Y0) / step);
  const grid = new Uint8Array(gw * gh);
  for (let j = 0; j < gh; j++) for (let i = 0; i < gw; i++) if (isPillPx(rgb(f, X0 + i * step, Y0 + j * step))) grid[j * gw + i] = 1;
  const out: Pill[] = [];
  for (const c of components(grid, gw, gh, false)) {
    const w = c.w * step / s, h = c.h * step / s;
    if (w < 26 || w > 200 || h < 20 || h > 40 || c.n < 0.45 * c.w * c.h) continue;
    const fx = X0 + c.x * step, fy = Y0 + c.y * step, fw = c.w * step, fh = c.h * step;
    const text = readPillText(f, fx, fy, fw, fh);
    const clean = text && /^\d[\d,]*(\.\d+)?$/.test(text) ? text : null;
    const value = clean ? Number(clean.replace(/,/g, "")) : null;
    out.push({ x: fx / s, y: fy / s, w, h, cx: (fx + fw / 2) / s, cy: (fy + fh / 2) / s, text, value: value !== null && Number.isFinite(value) ? value : null });
  }
  return out;
}
